const input = $json || {};

const sampleContext = {
  version: '1.0',
  generatedAt: new Date().toISOString(),
  timezone: 'Asia/Dubai',
  request: { text: 'Bu akşam ne yapayım?' },
  userContext: {
    identity: { name: 'Savaş', language: 'Turkish' },
    locations: { home: 'Palm Jumeirah, Dubai', work: 'Abu Dhabi' }
  },
  calendarContext: { today: [], tomorrow: [], thisWeek: [] },
  derivedContext: {
    isWeekend: true,
    calendarLoad: 'low',
    needsMoreSocial: true,
    needsMoreFitness: true
  }
};

const sampleDecision = {
  route: 'social_discovery',
  agentWorkflowName: 'Concierge OS - Social Discovery Agent',
  actionMode: 'discover_analyze_recommend',
  confidence: 0.90,
  isAmbiguous: false,
  needsDiscovery: true,
  requiresApproval: false,
  requiredContext: ['memory', 'calendar', 'derived_context'],
  reason: 'Manual test route.'
};

return [{
  json: {
    request: input.request || {
      text: 'Bu akşam ne yapayım?',
      channel: 'manual_test',
      userId: 'savas',
      conversationId: 'manual-test'
    },
    context: Object.keys(input.context || {}).length ? input.context : sampleContext,
    decision: Object.keys(input.decision || {}).length ? input.decision : sampleDecision,
    metadata: input.metadata || {
      sourceWorkflow: 'Manual Test',
      testMode: true
    }
  }
}];

const input = $json || {};
const request = input.request || {};
const context = input.context || {};
const decision = input.decision || {};
const metadata = {
  correlationId: input.metadata?.correlationId || `concierge-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,
  sourceWorkflow: input.metadata?.sourceWorkflow || 'Concierge OS - Agent Orchestrator',
  testMode: input.metadata?.testMode ?? false,
  ...input.metadata
};

const registry = {
  daily_planner: ['daily_planner','Concierge OS - Daily Planner','planning',true,'planned'],
  weekly_planner: ['weekly_planner','Concierge OS - Weekly Planner','planning',true,'available'],
  social_discovery: ['social_discovery','Concierge OS - Social Discovery Agent','social',true,'planned'],
  sports_fitness: ['sports_fitness','Concierge OS - Sports and Fitness Agent','fitness',true,'planned'],
  recovery_wellness: ['recovery_wellness','Concierge OS - Recovery and Wellness Coach','wellness',true,'planned'],
  style_grooming: ['style_grooming','Concierge OS - Style and Grooming Coach','style',true,'planned'],
  social_confidence: ['social_confidence','Concierge OS - Social Confidence Coach','social_confidence',true,'planned'],
  travel: ['travel','Concierge OS - Travel Scout','travel',true,'planned'],
  career_learning: ['career_learning','Concierge OS - Career and Learning Coach','career',true,'planned'],
  finance: ['finance','Concierge OS - Finance Coach','finance',true,'planned'],
  feedback: ['feedback','Concierge OS - Feedback Collector','feedback',false,'planned'],
  profile_update: ['profile_update','Concierge OS - Memory Manager','memory',false,'available'],
  calendar_action: ['calendar_action','Concierge OS - Calendar Approval','approval',false,'planned'],
  general_concierge: ['general_concierge','Concierge OS - General Concierge','general',true,'planned']
};

let route = String(decision.route || 'general_concierge');
const warnings = [];

if (!registry[route]) {
  warnings.push(`Unknown route '${route}', falling back to general_concierge.`);
  route = 'general_concierge';
}

const [agent, workflowName, category, requiresLLM, status] = registry[route];

const requiredContext = Array.isArray(decision.requiredContext) ? decision.requiredContext : [];
const missingContext = [];

if (requiredContext.includes('memory') && !context.userContext) missingContext.push('memory');
if (requiredContext.includes('calendar') && !context.calendarContext && !context.calendar) missingContext.push('calendar');
if (requiredContext.includes('derived_context') && !context.derivedContext && !context.derived) missingContext.push('derived_context');

if (missingContext.length) warnings.push(`Missing context: ${missingContext.join(', ')}.`);

const agentRequest = {
  request: {
    id: request.id || `${metadata.correlationId}-request`,
    text: String(request.text || ''),
    channel: request.channel || 'unknown',
    userId: String(request.userId || 'savas'),
    conversationId: String(request.conversationId || request.sessionId || metadata.correlationId),
    receivedAt: request.receivedAt || new Date().toISOString()
  },
  context,
  metadata: {
    ...metadata,
    selectedRoute: route,
    selectedAgent: agent,
    targetWorkflow: workflowName,
    actionMode: decision.actionMode || 'analyze_and_respond',
    decisionConfidence: Number(decision.confidence ?? 0),
    requiresApproval: Boolean(decision.requiresApproval),
    requiresLLM
  }
};

const executionStatus = status === 'available'
  ? 'ready_for_workflow_connection'
  : 'agent_not_implemented';

return [{
  json: {
    success: true,
    result: {
      selectedAgent: agent,
      selectedRoute: route,
      targetWorkflow: workflowName,
      category,
      requiresLLM,
      executionStatus,
      agentRequest
    },
    memoryUpdates: [],
    approvalRequests: decision.requiresApproval ? [{
      type: route,
      status: 'proposed',
      summary: `Approval may be required for route: ${route}`,
      payload: { route, targetWorkflow: workflowName }
    }] : [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Agent Orchestrator',
      level: warnings.length ? 'warning' : 'info',
      correlationId: metadata.correlationId,
      message: `Prepared dispatch for ${agent}.`,
      details: { route, targetWorkflow: workflowName, executionStatus, warnings }
    }],
    nextAction: {
      type: executionStatus === 'ready_for_workflow_connection'
        ? 'call_agent_workflow'
        : 'implement_or_connect_agent',
      targetWorkflow: workflowName
    },
    error: null
  }
}];

const envelope = $json || {};
if (!envelope.success) return [{json: envelope}];

const result = envelope.result || {};

if (result.executionStatus === 'agent_not_implemented') {
  result.agentResponse = {
    success: true,
    result: {
      agent: result.selectedAgent,
      summary: `The route '${result.selectedRoute}' was selected correctly, but '${result.targetWorkflow}' is not implemented yet.`,
      recommendations: []
    },
    memoryUpdates: [],
    approvalRequests: envelope.approvalRequests || [],
    logs: [],
    nextAction: {
      type: 'implement_agent',
      targetWorkflow: result.targetWorkflow
    },
    error: null
  };
}

return [{json: {...envelope, result}}];
